INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(5892, 'plPL', 'Zapasy z Żelaznej Głębi', 'Zanim zaczęły się walki, składowaliśmy zapasy dla Dun Baldar w Kopalni Żelaznej Głębi. Troggi, które wylazły tam na powierzchnię, nie były wielkim problemem, dopóki mieliśmy wolnych żołnierzy do pilnowania kopalni. Teraz jednak, gdy walczymy z Hordą, nie jesteśmy w stanie utrzymać Żelaznej Głębi.$B$BPotrzebujemy zapasów z Żelaznej Głębi, $N. Wejdź do kopalni i przynieś mi ich porządny ładunek.', 'Przynieś 10 zapasów z Żelaznej Głębi kwatermistrzowi Przymierza w Dun Baldar.', '', 'Wróć do kwatermistrza Gromdardy w Dun Baldar w Dolinie Alterak.', '', '', '', '', 0),
(5893, 'plPL', 'Zapasy z Mrozokłów', 'Kopalnia Mrozokłów na północy była kiedyś idealnym miejscem na składowanie dodatkowych zapasów. Teraz jednak, gdy walki z Gromdardą przybierają na sile, nie zawsze mamy wolnych wojowników, których moglibyśmy postawić na straży kopalni. Dlatego kopalnia często wpada w ręce Przymierza albo podziemnych stworów...$B$BMimo to wciąż potrzebujemy naszych zapasów, $N! Idź do Kopalni Mrozokłów i przynieś mi ich porządny ładunek. I uważaj po drodze na wrogów – w tamtym miejscu losy bitwy szybko się odwracają...', 'Przynieś 10 zapasów z Mrozokłów kwatermistrzowi Hordy w Twierdzy Mroźnych Wilków.', '', 'Wróć do kwatermistrza Mroźnych Wilków w Twierdzy Mroźnych Wilków w Dolinie Alterak.', '', '', '', '', 0),
(6741, 'plPL', 'Więcej łupów!', '', '', '', 'Wróć do kowala Regzara w Dolinie Alterak.', '', '', '', '', 0),
(6781, 'plPL', 'Więcej złomu pancernego', '', '', '', 'Wróć do Murgota Głębokucia w Dolinie Alterak.', '', '', '', '', 0),
(6801, 'plPL', 'Lokholar, Władca Lodu', '', '', '', 'Wróć do pramagini Thurlogi w Dolinie Alterak.', '', '', '', '', 0),
(6825, 'plPL', 'Zew powietrza – flota Guse', '', '', '', 'Wróć do dowódcy skrzydła Guse w Dolinie Alterak.', '', '', '', '', 0),
(6826, 'plPL', 'Zew powietrza – flota Jeztor', '', '', '', 'Wróć do dowódcy skrzydła Jeztor w Dolinie Alterak.', '', '', '', '', 0),
(6827, 'plPL', 'Zew powietrza – flota Mulvericka', '', '', '', 'Wróć do dowódcy skrzydła Mulvericka w Dolinie Alterak.', '', '', '', '', 0),
(6846, 'plPL', 'Rozpocznij atak!', '', '', '', 'Wróć do feldmarszałka Teravaine\'a w Dolinie Alterak.', '', '', '', '', 0),
(6847, 'plPL', 'Wszystkowidzące oko mistrza Rysona', 'Wasza wojna w sercu Alterak nic nie znaczy dla Syndykatu, $N. Zrobimy to, co zawsze: zaczekamy, aż z popiołów i gruzów tego szaleństwa wyłoni się wyraźny zwycięzca, a wtedy uderzymy.$B$BNie dlatego jednak teraz tu jesteśmy. Wszystkowidzące oko zaginęło – zabrały je tutejsze trolle z Zimowego Topora.$B$BOdzyskaj Oko, a nasze usługi będą twoje – na tyle czasu, ile zostało twojej stronie.$B$BWróć do mnie, gdy zdobędziesz oko, abym mógł cię zbadać.$B$B<Mistrz Ryson szczerzy zęby.>', 'Odzyskaj wszystkowidzące oko mistrza Rysona z jaskiń Zimowego Topora i zwróć je mistrzowi Rysonowi.$B$BStrzeż się – mówią, że na wszystkowidzącym oku mistrza Rysona ciąży straszliwa klątwa!', 'Wszystkowidzące oko mistrza Rysona odzyskane', 'Wróć do mistrza Syndykatu Rysona w Dolinie Alterak.', '', '', '', '', 0),
(6848, 'plPL', 'Wszystkowidzące oko mistrza Rysona', 'Wasza wojna w sercu Alterak nic nie znaczy dla Syndykatu, $N. Zrobimy to, co zawsze: zaczekamy, aż z popiołów i gruzów tego szaleństwa wyłoni się wyraźny zwycięzca, a wtedy uderzymy.$B$BNie dlatego jednak teraz tu jesteśmy. Wszystkowidzące oko zaginęło – zabrały je tutejsze trolle z Zimowego Topora.$B$BOdzyskaj Oko, a nasze usługi będą twoje – na tyle czasu, ile zostało twojej stronie.$B$BWróć do mnie, gdy zdobędziesz oko, abym mógł cię zbadać.$B$B<Mistrz Ryson szczerzy zęby.>', 'Odzyskaj wszystkowidzące oko mistrza Rysona z jaskiń Zimowego Topora i zwróć je mistrzowi Rysonowi.$B$BStrzeż się – mówią, że na wszystkowidzącym oku mistrza Rysona ciąży straszliwa klątwa!', 'Wszystkowidzące oko mistrza Rysona odzyskane', 'Wróć do mistrza Syndykatu Rysona w Dolinie Alterak.', '', '', '', '', 0),
(6861, 'plPL', 'Przenośny rozdrabniacz Zinfizzlexa', 'Nie mniej niż ty chcę wypróbować mój przenośny rozdrabniacz, ale zanim zbuduję zestaw, potrzebuję materiałów – mnóstwa materiałów!$B$BŚciśle mówiąc, potrzebuję całej góry torium, mithrilu i żelaza. Potrzebuję też jednej piły parowej na każdy egzemplarz. Te musisz zdobyć w tartaku.$B$BKiedy tu węszyłem (zanim mnie pojmali), zauważyłem stos pił parowych w obozie drwali Gromdardy.', 'Mistrz inżynier Zinfizzlex chce, abyś $gprzyniósł:przyniosła; mu:$B$B*30 sztab torium.$B$B*50 sztab mithrilu.$B$B*75 sztab żelaza.$B$B*1 piłę parową.$B', '', 'Wróć do mistrza inżyniera Zinfizzlexa w Dolinie Alterak.', '', '', '', '', 0),
(6862, 'plPL', 'Przenośny rozdrabniacz Zinfizzlexa', 'Nie mniej niż ty chcę wypróbować mój przenośny rozdrabniacz, ale zanim zbuduję zestaw, potrzebuję materiałów – mnóstwa materiałów!$B$BŚciśle mówiąc, potrzebuję całej góry torium, mithrilu i żelaza. Potrzebuję też jednej piły parowej na każdy egzemplarz. Te musisz zdobyć w tartaku.$B$BKiedy tu węszyłem (zanim mnie pojmali), zauważyłem stos pił parowych w obozie drwali Mroźnych Wilków.', 'Mistrz inżynier Zinfizzlex chce, abyś $gprzyniósł:przyniosła; mu:$B$B*30 sztab torium.$B$B*50 sztab mithrilu.$B$B*75 sztab żelaza.$B$B*1 piłę parową.$B', '', 'Wróć do mistrza inżyniera Zinfizzlexa w Dolinie Alterak.', '', '', '', '', 0),
(6881, 'plPL', 'Ivus, Władca Lasu', '', '', '', 'Wróć do arcydruidki Renferal w Dolinie Alterak.', '', '', '', '', 0),
(6901, 'plPL', 'Przypuść atak!', '', '', '', 'Wróć do mistrza wojennego Garricka w Dolinie Alterak.', '', '', '', '', 0),
(6941, 'plPL', 'Zew powietrza – flota Vipore\'a', '', '', '', 'Wróć do dowódcy skrzydła Vipore\'a w Dolinie Alterak.', '', '', '', '', 0),
(6942, 'plPL', 'Zew powietrza – flota Slidore\'a', '', '', '', 'Wróć do dowódcy skrzydła Slidore\'a w Dolinie Alterak.', '', '', '', '', 0),
(6943, 'plPL', 'Zew powietrza – flota Ichmana', '', '', '', 'Wróć do dowódcy skrzydła Ichmana w Dolinie Alterak.', '', '', '', '', 0),
(6982, 'plPL', 'Zapasy z Mrozokłów', 'Kopalnia Mrozokłów to skład zaopatrzenia Hordy. Nie przełknąłbym jedzenia, które dają swoim żołnierzom, a stan ich broni i pancerzy jest okropny! Ale... w takich czasach, gdy zapasy są tak ważne, możemy wykorzystać to, co mają.$B$BWejdź do Kopalni Mrozokłów i przynieś mi ich zapasy. Pomoże to utrzymać Przymierze w gotowości bojowej i odbierze wojownikom Hordy tak bardzo potrzebny sprzęt.$B$BPowodzenia, $N. Kopalnia leży daleko na południu, głęboko na terytorium Hordy.', 'Przynieś 10 zapasów z Mrozokłów kwatermistrzowi Przymierza w Dun Baldar.', '', 'Wróć do kwatermistrza Gromdardy w Dun Baldar w Dolinie Alterak.', '', '', '', '', 0),
(6985, 'plPL', 'Zapasy z Żelaznej Głębi', 'Krasnoludy z Gromdardy wykorzystują Kopalnię Żelaznej Głębi jako skład zaopatrzenia. Chcę, żebyś $gnapadł:napadła; na tę kopalnię i $gprzyniósł:przyniosła; mi jej zapasy. To ukróci poczynania Gromdardy w Dolinie Alterak i zapewni nam potrzebny sprzęt!$B$BUważaj, $N. Kopalnia Żelaznej Głębi leży głęboko na terytorium Przymierza, a władza nad nią jest zmienna jak śniegi Alterak.', 'Przynieś 10 zapasów z Żelaznej Głębi kwatermistrzowi Hordy w Twierdzy Mroźnych Wilków.', '', 'Wróć do kwatermistrza Mroźnych Wilków w Twierdzy Mroźnych Wilków w Dolinie Alterak.', '', '', '', '', 0),
(7001, 'plPL', 'Puste stajnie', 'Wojna w dolinie odcisnęła piętno na naszych żołnierzach. Musimy odbudować nasze siły!$B$BJeśli zdołamy zapełnić stajnie, wilczy jeźdźcy znów będą mogli wyruszyć na pole bitwy.$B$BWeź ten kaganiec i wytrop mroźne wilki zamieszkujące pobliski las. Gdy znajdziesz wilka, użyj kagańca, by oswoić bestię. Przyprowadź oswojone zwierzę do mnie, a umieszczę je w stajni.$B$BGdy w stajni będzie dość wilków, wilczy jeźdźcy wrócą na patrole na naszej linii frontu.', 'Znajdź mroźnego wilka w Dolinie Alterak. Użyj kagańca Mroźnych Wilków w pobliżu wilka, by „oswoić” bestię. Oswojony wilk pójdzie za tobą do stajennej Mroźnych Wilków. Porozmawiaj ze stajenną Mroźnych Wilków, by zaliczono ci schwytanie.', 'Mroźny wilk okiełznany i przyprowadzony', 'Wróć do stajennej Mroźnych Wilków w Dolinie Alterak.', '', '', '', '', 0),
(7002, 'plPL', 'Uprząż z baranich skór', '', '', '', 'Wróć do dowódcy wilczych jeźdźców Mroźnych Wilków w Dolinie Alterak.', '', '', '', '', 0),
(7026, 'plPL', 'Uprząż do jazdy na baranie', '', '', '', 'Wróć do dowódcy jeźdźców baranów Gromdardy w Dolinie Alterak.', '', '', '', '', 0),
(7027, 'plPL', 'Puste stajnie', 'Tylko spójrz na te stajnie, $N! Puste! Brygada Gromdardy nie ma na czym jeździć – kawaleria przestała istnieć.$B$BMusisz nam pomóc, $gżołnierzu:żołnierko;. Weź tę obrożę treningową i wyrusz w dzikie ostępy doliny. Odszukaj alterackie barany, które wędrują po okolicy, i użyj obroży, by schwytać jednego z nich. Gdy schwytasz barana, przyprowadź go do mnie, a umieszczę go w stajni.$B$BGdy będziemy mieć dość baranów, powiadomimy dowódcę jeźdźców baranów. Dzięki twojej pomocy kawaleria się odrodzi!', 'Znajdź alterackiego barana w Dolinie Alterak. Użyj obroży treningowej Gromdardy w pobliżu barana, by „oswoić” bestię. Oswojony baran pójdzie za tobą do stajennej. Porozmawiaj ze stajenną, by zaliczono ci schwytanie.$B', 'Baran w obroży i przyprowadzony', 'Wróć do stajennej Gromdardy w Dun Baldar w Dolinie Alterak.', '', '', '', '', 0),
(7121, 'plPL', 'Kwatermistrz', '$N, nasz kwatermistrz polecił mi kierować do niego nowych rekrutów. Potrzebuje zapasów ze składów w kopalniach Alterak i pewnie właśnie po nie cię wyśle.$B$BIdź drogą. Znajdziesz naszego kwatermistrza na zachodzie.', 'Porozmawiaj z kwatermistrzem Gromdardy.', '', '', '', '', '', '', 0),
(7123, 'plPL', 'Porozmawiaj z naszym kwatermistrzem', '$N, kwatermistrz Mroźnych Wilków szuka rekrutów do zadań w kopalniach Doliny Alterak. Porozmawiaj z nim, on powie ci więcej.$B$BIdź drogą na zachód do bunkra, potem wyjdź zachodnim wyjściem, a znajdziesz naszego kwatermistrza.', 'Porozmawiaj z kwatermistrzem Mroźnych Wilków.', '', '', '', '', '', '', 0),
(7221, 'plPL', 'Porozmawiaj z poszukiwaczką Łupikamień', 'Ach, $N, zgłaszasz się do służby? Świetnie, Gromdardzie przyda się każdy, kogo zdołamy zebrać!$B$BPorozmawiaj z poszukiwaczką Łupikamień w Dun Baldar. Werbuje ochotników do ważnej misji na terytorium wroga. Znajdziesz Łupikamień na dole garnizonu Dun Baldar.$B$BI rozglądaj się, idąc przez Dun Baldar. Jest tu mnóstwo roboty dla kogoś pracowitego, kto nie boi się pobrudzić sobie rąk.', 'Porozmawiaj z poszukiwaczką Łupikamień w garnizonie Dun Baldar.', '', '', '', '', '', '', 0),
(7222, 'plPL', 'Porozmawiaj z Voggahem Śmiertelnym Chwytem', '$GPrzybyłeś:Przybyłaś;, by walczyć? Dobrze! Cieszymy się, że jesteś w Alterak, $N. Krasnoludzcy intruzi i ich sojusznicy najeżdżają naszą dolinę, a my witamy każdego z Hordy, kto przyłączy się do nas w tej sprawiedliwej rzezi!$B$BPorozmawiaj z Voggahem Śmiertelnym Chwytem. Szuka ochotników do ważnej misji w warowni Przymierza w Dolinie Alterak!$B$BZnajdziesz Voggaha w Twierdzy Mroźnych Wilków.', 'Porozmawiaj z Voggahem w Twierdzy Mroźnych Wilków.', '', '', '', '', '', '', 0),
(7223, 'plPL', 'Złom pancerny', 'W Dolinie Alterak bez przerwy szaleją bitwy, a zapasy, które dostajemy z Żelaznej Kuźni, nie wystarczają, by wyposażyć nasze doświadczone oddziały.$B$BJeśli znajdziesz na polu bitwy złom pancerny, wesprzyj wysiłek wojenny i przynieś go do mnie!', 'Przynieś 20 sztuk złomu pancernego Murgotowi Głębokuciu w Dun Baldar.', '', 'Wróć do Murgota Głębokucia w Dun Baldar w Dolinie Alterak.', '', '', '', '', 0),
(7224, 'plPL', 'Łupy z wroga', 'Gdy walczysz z wrogiem, zbieraj kawałki jego pancerza i przynoś je do mnie. Zrobię z tego złomu pancerze dla naszych żołnierzy!', 'Przynieś 20 sztuk złomu pancernego kowalowi Regzarowi w Wiosce Mroźnych Wilków.', '', 'Wróć do kowala Regzara w Wiosce Mroźnych Wilków w Dolinie Alterak.', '', '', '', '', 0),
(7281, 'plPL', 'Braterska miłość', 'Tragiczne... Mój brat staje przeciw mnie na polu bitwy jako jeden z dowódców Gromdardy.$B$BSpośród czterech dowódców Gromdardy jest bez wątpienia najgroźniejszy. Może gdyby zginął, Królowa Banshee mogłaby go przemienić, tak jak przemieniła mnie – pokazać mu jego błędy...$B$BMojego brata znajdziesz głęboko na terytorium wroga. Zabij go i wróć do mnie. Ufam, że podołasz tej misji, $gżołnierzu:żołnierko;.$B$BI jeszcze jedno, $gżołnierzu:żołnierko;: nie idź $gsam:sama;.', 'Wyrusz na terytorium Gromdardy i zabij dowódcę Karla Philipsa. Gdy zadanie zostanie wykonane, wróć do dowódcy Louisa Philipsa.$B', '', 'Wróć do dowódcy Louisa Philipsa na Wieżowym Cyplu w Dolinie Alterak.', '', '', '', '', 0),
(7282, 'plPL', 'Braterska miłość', 'Trzeba skrócić jego cierpienia, $gżołnierzu:żołnierko;! On nie wie, co czyni. Stał się bezmyślnym sługą przeklętej Królowej Banshee.$B$BWyrusz przez Pole Niezgody w głąb terytorium Mroźnych Wilków. Znajdź mojego brata i zniszcz go. Jego męka musi się skończyć.', 'Wyrusz na terytorium Mroźnych Wilków i zabij dowódcę Louisa Philipsa. Gdy zadanie zostanie wykonane, wróć do dowódcy Karla Philipsa.$B', '', 'Wróć do dowódcy Karla Philipsa w Dolinie Alterak.', '', '', '', '', 0),
(7301, 'plPL', 'Upadli władcy przestworzy', 'Trzymamy ich w niewoli. Mówię o ich dowódcach skrzydła. To była zażarta bitwa w przestworzach, ale w końcu spadli! Niestety nasi najlepsi piloci zostali zestrzeleni podczas kontrataku na Twierdzę Mroźnych Wilków. Musisz się dowiedzieć, co się z nimi stało.$B$BPrzeszukaj Zachodni Wieżowy Cypel i Twierdzę Mroźnych Wilków. To ich ostatnie znane położenie. Dokładnie przeszukaj te tereny.', 'Wyrusz na terytorium Mroźnych Wilków i odszukaj dowódcę skrzydła Slidore\'a, dowódcę skrzydła Vipore\'a i dowódcę skrzydła Ichmana. Jeśli wykonasz misję, wróć do dowódcy Duffy\'ego.', '', 'Wróć do dowódcy Duffy\'ego w Dolinie Alterak.', 'Odkryto miejsce pobytu Ichmana', 'Odkryto miejsce pobytu Vipore\'a', 'Odkryto miejsce pobytu Slidore\'a', '', 0),
(7302, 'plPL', 'Upadli władcy przestworzy', 'Nasze wsparcie powietrzne leży w gruzach, $N. Dowódców skrzydła zestrzelono nad terytorium wroga. Musisz się dowiedzieć, co się z nimi stało, żebyśmy mogli spróbować ich odbić!$B$BGuse ostatnio widziano, gdy przelatywała nad Bunkrem Lodowego Skrzydła. Jeźdźca wojennego Jeztor dostrzeżono w pobliżu tartaku Gromdardy. Mulverick... tego lekkomyślnego głupca widziano, jak rozbija się w pobliżu Północnego Bunkra Dun Baldar.$B$BTo wszystkie informacje, jakie mam. Ruszaj! Dokładnie przeszukaj te tereny.', 'Dowiedz się, co się stało z dowódcą skrzydła Guse, dowódcą skrzydła Jeztor i dowódcą skrzydła Mulverickiem. Jeśli wykonasz misję, wróć do dowódcy Mulforta.', '', 'Wróć do dowódcy Mulforta w Wiosce Mroźnych Wilków w Dolinie Alterak.', 'Odkryto miejsce pobytu Guse', 'Odkryto miejsce pobytu Jeztor', 'Odkryto miejsce pobytu Mulvericka', '', 0),
(7361, 'plPL', 'Przychylność Mrocznej Włóczni', '<Najak warczy.>$B$BZanim istniały nocne elfy, był troll. To z trolla wywodzą się nocne elfy.$B$BIch buntownicze ataki na mój lud nie będą tolerowane. Jeleniorogi chce nas wytępić – nie zostawić śladu po tych, z których zrodził się on i jemu podobni. Do tego nie dojdzie!$B$BZa każdego nocnego elfa, którego zabijesz i pozbawisz głowy, Najak zapewni ci przychylność Mrocznej Włóczni. Wieść o twoich czynach rozejdzie się po Kalimdorze i Wschodnich Królestwach. Idź teraz i służ Mrocznej Włóczni!', 'Masz zabijać graczy nocnych elfów walczących po stronie wroga w Dolinie Alterak.$B$BZabij nocnego elfa i wróć do Najaka Hexxena w Twierdzy Mroźnych Wilków z odciętą głową nocnego elfa.', '', 'Wróć do Najaka Hexxena w Wiosce Mroźnych Wilków w Dolinie Alterak.', '', '', '', '', 0),
(7362, 'plPL', 'Sojusznik taurenów', 'Wiedźma starszyzny przysłała mnie na tę wojnę, bym badał inne rasy. Dokładniej mówiąc, mam zebrać próbki gnomów. Magata interesuje się przede wszystkim ich przeżywalnością. Tak, gnomy – choć żałośnie słabe i maleńkie – wykazują wielką odporność, zarówno w walce, jak i poza nią.$B$BNa twoje szczęście szukam zabijaków, którzy wykonają polecenia Magaty. Wróć do mnie z kępkami gnomich włosów, a taureni uznają cię za sojusznika.', 'Masz zabijać graczy gnomów walczących po stronie wroga w Dolinie Alterak.$B$BZabij gnoma i wróć do Ravaka Ponurego Totemu w Twierdzy Mroźnych Wilków z kępką gnomich włosów.', '', 'Wróć do Ravaka Ponurego Totemu w Wiosce Mroźnych Wilków w Dolinie Alterak.', '', '', '', '', 0),
(7363, 'plPL', 'Ludzka przypadłość', 'Ludzie są tak bezgranicznie odrażający.$B$B<Dowódca Philips się krzywi.>$B$BTo prawda, że jestem żołnierzem Mroźnych Wilków, ale wciąż pozostaję sługą Sylwany.$B$BPodczas służby dorabiam na boku dla Mrocznych Aptekarzy z Podmiasta.$B$BPowierzono mi zbieranie odłamków ludzkich kości, które mają posłużyć do leczenia ludzkiej przypadłości.$B$BMam prawo przekazać to zadanie moim podwładnym.$B$BZnajdź ich. Zabij ich. Przynieś mi odłamki ich kości.', 'Masz zabijać graczy ludzi walczących po stronie wroga w Dolinie Alterak.$B$BZabij człowieka i wróć z odłamkiem ludzkiej kości do dowódcy Louisa Philipsa (który krąży między linią frontu a Twierdzą Mroźnych Wilków).$B$BLekarstwo na ludzką przypadłość jest na wyciągnięcie ręki!', '', 'Wróć do dowódcy Louisa Philipsa na Wieżowym Cyplu w Dolinie Alterak.', '', '', '', '', 0),
(7364, 'plPL', 'Nagroda Gnomoregan', 'Sam Wielki Majster przysłał mnie na to pole bitwy, bym bronił moich gnomich braci i sióstr. Dotarły do nas wieści, że taureni wyłapują i zabijają gnomy. A co najgorsze, wyrywają kępki wspaniałych gnomich włosów z ciał poległych. Te okrucieństwa trzeba powstrzymać. Musimy odpłacić pięknym za nadobne!$B$BChcę, żeby zostali pozbawieni kopyt, $N. Przynieś mi ich kopyta! Pokaż, że jesteś sojusznikiem gnomów.', 'Masz zabijać graczy taurenów walczących po stronie wroga w Dolinie Alterak.$B$BZabij taurena i wróć z kopytem taurena do Dirka Szwindla w Dun Baldar.', '', 'Wróć do Dirka Szwindla w Dun Baldar w Dolinie Alterak.', '', '', '', '', 0),
(7365, 'plPL', 'Requiem Jeleniorogiego', 'Jeleniorogi wydał rozkaz. Wszystkie trolle na polu bitwy mają zostać wytępione. Na ich niedorzeczne twierdzenia, że to z nich zrodziły się nocne elfy, trzeba odpowiedzieć siłą i należytą bezwzględnością.$B$BZabij ich i wróć do mnie z ich mojo. Powtarzam: chcę, żebyś $gukradł:ukradła; im mojo.', 'Masz zabijać graczy trolli walczących po stronie wroga w Dolinie Alterak.$B$BZabij trolla i wróć z mojo trolla z Mrocznej Włóczni do Athramanisa w Dun Baldar.', '', 'Wróć do Athramanisa w Dun Baldar w Dolinie Alterak.', '', '', '', '', 0),
(7366, 'plPL', 'Łaska arcybiskupa', 'Arcybiskup jest równie łaskawy, co mądry. Żeby patrzeć z miłosierdziem na tak nikczemną zgraję...$B$B<Dowódca Philips kręci głową z niedowierzaniem.>$B$BZa łaskawy... Po prostu za łaskawy.$B$BArcybiskup prosi, byśmy zlitowali się nad nieumarłymi i obdarzyli ich szybką i ostateczną śmiercią. W zamian za ten wspaniały akt miłosierdzia potrzebujemy jedynie ich czarnych, przeżartych chorobą serc.$B$BPrzynieś mi serca Porzuconych, aby mogły zostać uroczyście spalone w Katedrze Światła. Pospiesz się, $N!', 'Masz zabijać graczy Porzuconych walczących po stronie wroga w Dolinie Alterak.$B$BZabij Porzuconego i wróć z sercem Porzuconego do dowódcy Karla Philipsa (który krąży między tartakiem a kopalnią).', '', 'Wróć do dowódcy Karla Philipsa w Dolinie Alterak.', '', '', '', '', 0),
(7367, 'plPL', 'Rozbrojenie zagrożenia', 'Mroźne Wilki zaminowały swoją linię frontu i bazy, $N. Wkraczając na terytorium wroga, trzeba patrzeć pod nogi.$B$BJeśli chcesz zadać im solidny cios, musisz zniszczyć źródło ich amunicji przeciwpiechotnej – mówię o ich ekspercie od materiałów wybuchowych. Jeśli go zabijesz, $gbędziesz mógł:będziesz mogła; bezpiecznie rozbrajać miny. Dopóki on leży, miny też nie wrócą.$B$BZnajdziesz go pewnie w wieży w pobliżu Garnizonu Lodowej Posoki. Powodzenia!', 'Znajdź eksperta od materiałów wybuchowych Mroźnych Wilków i zabij go. Gdy zadanie zostanie wykonane, wróć do eksperta od materiałów wybuchowych Gromdardy.', '', 'Wróć do eksperta od materiałów wybuchowych Gromdardy w Dolinie Alterak.', '', '', '', '', 0),
(7368, 'plPL', 'Rozbrojenie zagrożenia', 'Wiem o minach wszystko. W końcu to ja rozkładam wszystkie miny na tutejszej linii frontu.$B$BJeśli chcesz rozbroić pola minowe Gromdardy, musisz tylko zabić ich eksperta od materiałów wybuchowych. Ten krasnoludzki tchórz bez wątpienia kryje się w pierwszej wieży na Polu Niezgody. Zlikwiduj go, a rozbrojone miny już nie wrócą.$B$BJeśli uda ci się go zabić, wróć tu i daj mi znać. Żaden dobry uczynek nie powinien pozostać bez nagrody.', 'Znajdź eksperta od materiałów wybuchowych Gromdardy i zabij go. Gdy zadanie zostanie wykonane, wróć do eksperta od materiałów wybuchowych Mroźnych Wilków.', '', 'Wróć do eksperta od materiałów wybuchowych Mroźnych Wilków w Dolinie Alterak.', '', '', '', '', 0),
(7385, 'plPL', 'Galon krwi', '', '', '', 'Wróć do pramagini Thurlogi w Dolinie Alterak.', '', '', '', '', 0),
(7386, 'plPL', 'Skupisko kryształów', '', '', '', 'Wróć do arcydruidki Renferal w Dolinie Alterak.', '', '', '', '', 0),
(7401, 'plPL', 'Poszukiwane: KRASNOLUDY!', 'Z rozkazu sierżant Yazry Krwawy Warkot wszystkie krasnoludy na polu bitwy mają być zabijane bez ostrzeżenia.$B$BJeśli zabijesz krasnoluda w walce, wyrwij mu kręgosłup, a cuchnąca, gnijąca kupa bez kręgosłupa niech będzie przestrogą dla każdego, kto ośmieli się przeciwstawić potędze Mroźnych Wilków.$B$BWróć do sierżant Yazry Krwawy Warkot z dowodem swojego bohaterstwa.', 'Masz zabijać graczy krasnoludów walczących po stronie wroga w Dolinie Alterak.$B$BZabij krasnoluda i wyrwij mu kręgosłup. Zanieś kręgosłup krasnoluda sierżant Yazrze Krwawy Warkot w Twierdzy Mroźnych Wilków.', '', 'Wróć do sierżant Yazry Krwawy Warkot w Dolinie Alterak.', '', '', '', '', 0),
(7402, 'plPL', 'Poszukiwani: ORKOWIE!', 'Z rozkazu kaprala Norega Gromdardy wszyscy zdolni do walki żołnierze Gromdardy mają zabijać każdego wrogiego orka, którego spotkają na polu bitwy.$B$BŻołnierze mają wyrwać kieł lub ząb z paszczy wroga i przedstawić go jako dowód wykonania zadania.$B$BNależy nosić rękawice ochronne.', 'Masz zabijać graczy orków walczących po stronie wroga w Dolinie Alterak.$B$BZabij orka i zanieś jego ząb kapralowi Noregowi Gromdardzie w Dun Baldar.', '', 'Wróć do kaprala Norega Gromdardy w Dun Baldar w Dolinie Alterak.', '', '', '', '', 0),
(7421, 'plPL', 'Obrona Mrocznej Włóczni', '', '', '', 'Wróć do Najaka Hexxena w Dolinie Alterak.', '', '', '', '', 0),
(7422, 'plPL', 'Kępka za kępką', '', '', '', 'Wróć do Ravaka Ponurego Totemu w Dolinie Alterak.', '', '', '', '', 0),
(7423, 'plPL', 'Mam gorączkę i lekiem są odłamki kości', '', '', '', 'Wróć do dowódcy Louisa Philipsa w Dolinie Alterak.', '', '', '', '', 0),
(7424, 'plPL', 'Co jest, do kopyta?', '', '', '', 'Wróć do Dirka Szwindla w Dolinie Alterak.', '', '', '', '', 0),
(7425, 'plPL', 'Mojo-feta Jeleniorogiego', '', '', '', 'Wróć do Athramanisa w Dolinie Alterak.', '', '', '', '', 0),
(7426, 'plPL', 'Miłość jednego człowieka', '', '', '', 'Wróć do dowódcy Karla Philipsa w Dolinie Alterak.', '', '', '', '', 0),
(7427, 'plPL', 'Poszukiwane: WIĘCEJ KRASNOLUDÓW!', '', '', '', 'Wróć do sierżant Yazry Krwawy Warkot w Dolinie Alterak.', '', '', '', '', 0),
(7428, 'plPL', 'Poszukiwani: WIĘCEJ ORKÓW!', '', '', '', 'Wróć do kaprala Norega Gromdardy w Dolinie Alterak.', '', '', '', '', 0),
(11336, 'plPL', 'Wezwanie do boju: Dolina Alterak', 'Walka na wielu frontach, $gchłopcze:dziewczyno;, oznacza, że nie możemy zbytnio rozpraszać sił, bo ryzykujemy utratę wszystkiego!$B$BKażdego dnia trzeba kierować wojska tam, gdzie są najbardziej potrzebne. Dziś to bitwa o Dolinę Alterak najbardziej potrzebuje dzielnych wojowników.$B$BIdź, $N, i wesprzyj Ekspedycję Gromdardy. Nie możemy pozwolić, by Klanowi Mroźnego Wilka uszła na sucho przemoc wobec naszych braci!', 'Wygraj bitwę w Dolinie Alterak i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.$B', 'Zwycięstwo w Dolinie Alterak', 'Wróć do generała brygady Przymierza.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(5892, 'plPL', 'Dobra robota! Zrobię z tych zapasów dobry użytek! Dzięki, $N!', 0),
(5893, 'plPL', 'Ach, masz je. Dobra robota, $N! Te zapasy trochę zatęchły od długiego leżenia w tej ciemnej kopalni, ale i tak zrobimy z nich użytek.$B$BDziękuję ci, $N. Twoje czyny są niezbędne do utrzymania naszych sił bojowych.', 0),
(6741, 'plPL', 'Jeszcze raz dzięki, $N. Przynosisz Hordzie chlubę...', 0),
(6781, 'plPL', 'To porządne kawałki, $N. Mogę z nich wykuć nowy ekwipunek dla naszych żołnierzy.$B$BJeśli moje zapasy wystarczająco urosną, może na pole bitwy wyruszą nasze doświadczone oddziały!', 0),
(6801, 'plPL', 'Krew naszych wrogów została przelana. Zmieszam ją z resztą zebranej krwi. Gdy ofiara zostanie dopełniona, Władca Lodu pokaże tym psom z Gromdardy pełnię gniewu Klanu Mroźnego Wilka!', 0),
(6825, 'plPL', 'Flota żywi się ich ciałami. Pożera wroga.$B$BWylot już wkrótce!', 0),
(6826, 'plPL', 'Więcej! Więcej! Przynoś więcej, bo wkrótce będą gotowi!', 0),
(6827, 'plPL', 'Za mało! Takiej roboty spodziewałbym się po nowicjuszu, ale po tobie, $N? No dalej, $gżołnierzu:żołnierko;! RUSZAJ SIĘ! Potrzeba więcej ciał!', 0),
(6846, 'plPL', 'Ach, rozkazy! Mówią, że mam atakować wedle własnej woli, a moja wola mówi... teraz!', 0),
(6881, 'plPL', 'Dobra robota, $N. Użyję mocy tego amuletu, by wzmocnić zebraną już magię. Gdy zgromadzimy dość mocy, skupię zebraną energię i wezwę Władcę Lasu, by wsparł naszą sprawę.', 0),
(6901, 'plPL', 'Najwyższy czas! Teraz pokażemy Przymierzu, jaką głupotą było przybycie do Doliny Alterak!', 0),
(6941, 'plPL', 'Eskadra wkrótce będzie gotowa. Nie ustawaj w wysiłkach!', 0),
(6942, 'plPL', 'Przynoś ich więcej, $gżołnierzu:żołnierko;! Gryfy z Orlego Gniazda w mig będą gotowe do ataku!', 0),
(6943, 'plPL', 'Widzisz to? Spójrz na nie, $gżołnierzu:żołnierko;! Dochodzą do siebie... Wkrótce eskadra Ichmana znów uderzy w samo serce doliny! Gromdarda będzie panować w przestworzach!', 0),
(6982, 'plPL', 'Ach, masz je. Dobra robota, $N! Te zapasy trochę zatęchły od długiego leżenia w tej ciemnej kopalni, ale i tak zrobimy z nich użytek.$B$BDziękuję ci, $N. Twoje czyny są niezbędne do utrzymania naszych sił bojowych.', 0),
(6985, 'plPL', 'Masz je! Świetna robota, $N! Mam nadzieję, że podczas wypadu $gspotkałeś:spotkałaś; kilka krasnoludów i $gprzelałeś:przelałaś; ich krew za Mroźne Wilki!', 0),
(7001, 'plPL', 'Mogę tylko mieć nadzieję, że ci, którym powierzono zbieranie skór baranów, są równie wytrwali jak ty, $N.$B$BW tym tempie zapełnimy stajnie w ciągu kilku godzin!', 0),
(7002, 'plPL', 'Dobra robota, $gżołnierzu:żołnierko;. Dam ci znać, gdy zgromadzę dość skór.$B$BWracaj do roboty!', 0),
(7026, 'plPL', 'Dobra robota, $gżołnierzu:żołnierko;. Dam ci znać, gdy zgromadzę dość skór.$B$BWracaj do roboty!', 0),
(7027, 'plPL', 'Stajnie w mig się zapełnią. Tak trzymaj!', 0),
(7121, 'plPL', 'Dobrze widzieć tu świeże oddziały, $N, ale przy odrobinie szczęścia trafisz w wir walki i długo nie pozostaniesz $gświeży:świeża;!$B$BPorozmawiaj ze mną ponownie. Mam zadania, które muszę z tobą omówić....', 0),
(7123, 'plPL', 'Witaj, $N! Dobrze widzieć kogoś takiego jak ty, kto chętnie wnosi swój wkład w sprawę Hordy. Porozmawiaj ze mną ponownie, bo mam dla ciebie ważne zadania...', 0),
(7223, 'plPL', 'To porządne kawałki, $N. Mogę z nich wykuć nowy ekwipunek dla naszych żołnierzy.$B$BJeśli moje zapasy wystarczająco urosną, może na pole bitwy wyruszą nasze doświadczone oddziały!', 0),
(7224, 'plPL', 'Te się nadadzą. Przetopię je i połatam, i nikt się nie domyśli, że pochodzą od tych tchórzy z Gromdardy!$B$BDzięki, $N. A teraz pozwól, że wypoleruję ci tę zbroję...', 0),
(7281, 'plPL', 'Twoje bohaterstwo nie przejdzie niezauważone, $N.$B$BNie mogę tracić czasu, jeśli mamy go ocalić. Trzeba powiadomić Sylwanę!', 0),
(7282, 'plPL', 'Nie $gzapomniałeś:zapomniałaś; spalić zwłok, prawda?', 0),
(7301, 'plPL', 'Niewiarygodne! $GUwolniłeś:Uwolniłaś; ich, prawda? Prawda??? No, przynajmniej wiemy, gdzie ich trzymano.', 0),
(7302, 'plPL', 'Dobra robota! Zdobyte przez ciebie informacje będą bezcenne dla naszej sprawy.', 0),
(7361, 'plPL', '$N, to dopiero jeden z tysięcy. Mimo to dobra robota.', 0),
(7362, 'plPL', 'Tak, to bez wątpienia gnom. Dobra robota, ale jest jeszcze więcej do zrobienia.', 0),
(7363, 'plPL', 'Byłoby łatwiej, gdyby po prostu pogodzili się ze swoją chorobą i poddali twojemu uzdrawiającemu dotykowi. Ale pewnie byłoby też mniej zabawy. Tak trzymaj! Wyleczymy ich, tak czy inaczej.', 0),
(7366, 'plPL', 'Chwała Benedyktowi! Kolejna zagubiona dusza, którą wkrótce ocalą białe, rozżarzone płomienie Światłości!$B$BIdź, o $gżołnierzu:żołnierko; Światłości! Trzeba ocalić więcej!', 0),
(7385, 'plPL', 'Krew naszych wrogów została przelana. Zmieszam ją z resztą zebranej krwi. Gdy ofiara zostanie dopełniona, Władca Lodu pokaże tym psom z Gromdardy pełnię gniewu Klanu Mroźnego Wilka!', 0),
(7386, 'plPL', 'Dobra robota, $N. Użyję mocy tych amuletów, by wzmocnić zebraną już magię. Gdy zgromadzimy dość mocy, skupię zebraną energię i wezwę Władcę Lasu, by wsparł naszą sprawę.', 0),
(7401, 'plPL', 'Masz teraz pozwolenie na dziesiątkowanie krasnoludów tuzinami, $N!$B$B<Yazra przez chwilę wpatruje się w dal.>$B$BPierwszego wyrwanego kręgosłupa nigdy się nie zapomina...', 0),
(7424, 'plPL', '*Dirk rzuca kopyto na stos za sobą.*', 0),
(11336, 'plPL', 'Właśnie to chciałem usłyszeć! Zwycięstwo w Dolinie Alterak – nawet tymczasowe – ma kluczowe znaczenie dla naszej ogólnej strategii przeciw Hordzie.', 0),
(11340, 'plPL', 'Nie ma większego zaszczytu niż wypędzanie najeźdźców z ziem Hordy. Oddajemy hołd twojej wielkiej odwadze, z jaką $gwsparłeś:wsparłaś; dziś nasze siły!', 0),
(13428, 'plPL', 'Nie ma większego zaszczytu niż wypędzanie najeźdźców z ziem Hordy. Oddajemy hołd twojej wielkiej odwadze, z jaką $gwsparłeś:wsparłaś; dziś nasze siły!', 0),
(24426, 'plPL', 'Nie ma większego zaszczytu niż wypędzanie najeźdźców z ziem Hordy. Oddajemy hołd twojej wielkiej odwadze, z jaką $gwsparłeś:wsparłaś; dziś nasze siły!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(5892, 'plPL', 'Masz zapasy, $N? Nigdy nie mamy ich za dużo!', 0),
(5893, 'plPL', '$GByłeś:Byłaś; w Kopalni Mrozokłów, $N? Masz zapasy, o które prosiłem?', 0),
(6741, 'plPL', 'Potrzebuję więcej złomu pancernego, $N! Masz trochę?', 0),
(6781, 'plPL', '$N, potrzebujemy więcej złomu pancernego, by zaopatrzyć nasze oddziały!', 0),
(6801, 'plPL', 'Przybywam z Gromowych Urwisk. Sam Kairn dopilnował, bym w tych ciężkich czasach wspierała Klan Mroźnego Wilka.$b$bAle nie traćmy więcej czasu. Musisz powalić naszych wrogów i przynieść mi ich krew. Gdy zbierzemy jej dość, będzie można rozpocząć rytuał przywołania.$b$bZwycięstwo będzie pewne, gdy władca żywiołów zostanie spuszczony na armię Gromdardy.', 0),
(6825, 'plPL', 'Musimy przygotować nową flotę jeźdźców wojennych! Moi jeźdźcy mają uderzyć na centralne pole bitwy, ale najpierw muszę zaostrzyć ich apetyt – przygotować ich do natarcia.$b$bPotrzebuję tyle ciał żołnierzy Gromdardy, żeby wykarmić całą flotę! Setki funtów! Na pewno sobie z tym poradzisz, prawda? Ruszaj!', 0),
(6826, 'plPL', '$GCiężko pracowałeś:Ciężko pracowałaś;, $n, ale dopiero zaczęliśmy!$b$bMoi jeźdźcy wojenni muszą posmakować ciała swoich celów. To zapewni chirurgicznie precyzyjne uderzenie w naszych wrogów!$b$bMoja flota jest drugą co do siły w naszym dowództwie powietrznym. Dlatego uderzy na potężniejszych spośród naszych przeciwników. Do tego potrzebuje ciał poruczników Gromdardy.$b$bPospiesz się, $gżołnierzu:żołnierko;!', 0),
(6827, 'plPL', 'Przez wiele dni siedziałem zamknięty w krasnoludzkiej norze. Możesz mi wierzyć, że pragnę zemsty!$b$bMusimy wszystko starannie zaplanować.$b$bPo pierwsze, moi jeźdźcy wojenni potrzebują celów, na które mogą polować – celów najwyższej wagi. Będę musiał nakarmić ich ciałami dowódców Gromdardy. Niestety, te małe szkodniki okopały się głęboko za linią wroga! Czeka cię kawał roboty.', 0),
(6846, 'plPL', 'Moje oddziały są zaopatrzone i gotowe do natarcia. Potrzebujemy tylko rozkazów od Norega Gromdardy, a poślę je w wir walki!', 0),
(6881, 'plPL', 'Klan Mroźnego Wilka chroni skaza żywiołów. Ich szamani mieszają się do mocy, które, jeśli nikt ich nie powstrzyma, z pewnością zniszczą nas wszystkich.$b$bSzkody urosły tak bardzo, że Krąg nie jest w stanie nad nimi zapanować! Trzeba wezwać Ivusa na pomoc.$b$bŻołnierze Mroźnych Wilków noszą amulety żywiołów zwane kryształami burzy. Możemy ich użyć, by przywołać Ivusa. Ruszaj i zdobądź te kryształy, $n!', 0),
(6941, 'plPL', 'Trzeba się rozprawić z elitarnymi oddziałami Mroźnych Wilków, które pilnują linii, $gżołnierzu:żołnierko;! Rozkazuję ci przerzedzić to stado dzikusów. Wróć do mnie z medalami ich poruczników i legionistów. Gdy uznam, że dość tej hołoty zostało rozgromione, wyślę uderzenie z powietrza.', 0),
(6942, 'plPL', 'Moje gryfy są gotowe uderzyć na linię frontu, ale nie mogą zaatakować, dopóki linie nie zostaną przerzedzone.$b$bWojownicy Mroźnych Wilków, którym powierzono utrzymanie linii frontu, dumnie noszą na piersiach medale za służbę. Zedrzyj te medale z ich gnijących trucheł i przynieś je tutaj.$b$bGdy linia frontu zostanie dostatecznie przerzedzona, wezwę wsparcie z powietrza! Śmierć z nieba!', 0),
(6943, 'plPL', 'Ich duch jest słaby, $gżołnierzu:żołnierko;. Po naszym ostatnim nieudanym nalocie na Hordę nie chcą latać! Od ciebie zależy, czy podniesiesz ich morale.$B$BWróć na pole bitwy i uderz w samo serce dowództwa Mroźnych Wilków. Powal ich dowódców i strażników. Wróć do mnie z taką liczbą ich medali, jaką zdołasz upchnąć w plecaku! Obiecuję ci, że gdy moje gryfy zobaczą te łupy i poczują krew naszych wrogów, znów wzbiją się w powietrze! Idź już!', 0),
(6982, 'plPL', '$GByłeś:Byłaś; w Kopalni Mrozokłów, $N? Masz zapasy, o które prosiłem?', 0),
(6985, 'plPL', '$GByłeś:Byłaś; w Kopalni Żelaznej Głębi, $N? $GZłupiłeś:Złupiłaś; jej zapasy?', 0),
(7001, 'plPL', 'Bez twojej pomocy wilczy jeźdźcy Mroźnych Wilków nie mieliby wierzchowców, na których mogliby ruszyć do bitwy. Oddajesz nam wielką przysługę!', 0),
(7002, 'plPL', 'Podczas gdy część naszych żołnierzy łapie wilki dla stajennej, inni muszą zapewnić podstawowe rzeczy, których wymaga jazda wierzchem. Mówię oczywiście o uprzężach.$B$BMusisz uderzyć na barany żyjące w tym regionie. Te same barany, których kawaleria Gromdardy używa jako wierzchowców!$B$BZabijaj je i wracaj do mnie z ich skórami. Gdy zbierzemy dość skór, zrobimy z nich uprzęże dla jeźdźców. Wilczy jeźdźcy Mroźnych Wilków znów wyruszą do boju!', 0),
(7026, 'plPL', 'Brygada Gromdardy nie może ruszyć do szarży na oklep! Potrzebujemy uprzęży dla naszych wierzchowców, w końcu nie jesteśmy dzikusami.$B$BMoglibyśmy z łatwością zabić barany kręcące się w pobliżu naszej bazy, by zdobyć skórę na uprzęże, ale byłoby to idiotyczne. Te barany są nam potrzebne jako wierzchowce.$B$BMusisz uderzyć na bazę wroga, zabić mroźne wilki, których używają jako wierzchowców, i zabrać ich skóry. Przynieś mi te skóry, żebyśmy mogli zrobić uprzęże dla kawalerii. Ruszaj!', 0),
(7027, 'plPL', 'Bez twojej pomocy jeźdźcy baranów Gromdardy nie mieliby wierzchowców, na których mogliby ruszyć do bitwy. Oddajesz nam wielką przysługę!', 0),
(7223, 'plPL', '$GPrzyniosłeś:Przyniosłaś; jakiś złom pancerny, $N?', 0),
(7224, 'plPL', 'Jak idą łowy, $N? Masz dla mnie trochę złomu pancernego?', 0),
(7281, 'plPL', 'Jakże musi go boleć, że wciąż pozostaje wśród żywych, podczas gdy jego ukochany brat wzniósł się do doskonałości.', 0),
(7282, 'plPL', 'Z ciężkim sercem wydaję taki rozkaz, $gżołnierzu:żołnierko;.', 0),
(7301, 'plPL', 'Masz coś, co chciałbym usłyszeć?', 0),
(7302, 'plPL', 'Jak idą poszukiwania, $gżołnierzu:żołnierko;?', 0),
(7361, 'plPL', 'Chcą nas wytępić? To oni zostaną wytępieni.', 0),
(7362, 'plPL', 'Nie obchodzi mnie, skąd pochodzą te włosy.', 0),
(7363, 'plPL', 'Tak, to prawda. Mój brat jest człowiekiem. Hańba... Plama na mojej niemal nieskazitelnej karcie.', 0),
(7366, 'plPL', 'Benedykt! Jestem ledwie pyłkiem w cieniu jego wielkości. Chwała mu!', 0),
(7385, 'plPL', 'Możesz też ofiarować większe ilości krwi odebranej naszym wrogom. Z radością przyjmę ofiary liczone w galonach, $n.', 0),
(7386, 'plPL', 'Bywa, że walki ciągną się dniami albo tygodniami. Podczas takich dłuższych zmagań możesz zebrać duże skupiska kryształów burzy Mroźnych Wilków.$B$BKrąg przyjmuje takie ofiary, $n.', 0),
(7401, 'plPL', 'Ironią handluję hurtowo, $gżołnierzu:żołnierko;.', 0),
(8369, 'plPL', 'Jakie wieści przynosisz z ziem Mroźnych Wilków? Jak przebiega bitwa o Dolinę Alterak?', 0),
(11335, 'plPL', 'Powiedz mi, $n, jakie wieści przynosisz z frontu?', 0),
(11336, 'plPL', 'Powiedz mi, $n, jakie wieści przynosisz z frontu?', 0),
(11337, 'plPL', 'Powiedz mi, $n, jakie wieści przynosisz z frontu?', 0),
(11338, 'plPL', 'Powiedz mi, $n, jakie wieści przynosisz z frontu?', 0),
(11340, 'plPL', '$GWróciłeś:Wróciłaś;! Przynosisz wieści o zwycięstwie?', 0),
(13427, 'plPL', 'Powiedz mi, $N, jakie wieści przynosisz z frontu?', 0),
(13428, 'plPL', '$GWróciłeś:Wróciłaś;! Przynosisz wieści o zwycięstwie?', 0),
(14178, 'plPL', 'Powiedz mi, $n, jakie wieści przynosisz z frontu?', 0),
(14179, 'plPL', 'Powiedz mi, $n, jakie wieści przynosisz z frontu?', 0),
(14182, 'plPL', '$GWróciłeś:Wróciłaś;! Przynosisz wieści o zwycięstwie?', 0),
(14183, 'plPL', '$GWróciłeś:Wróciłaś;! Przynosisz wieści o zwycięstwie?', 0);
