INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`, `VerifiedBuild`) VALUES
(14558, 'plPL', 'Wisior lady Maye', '', 0),
(17353, 'plPL', 'Rozkazy natarcia Gromdardy', '', 0),
(17384, 'plPL', 'Przenośny rozdrabniacz Zinfizzlexa', '', 0),
(17410, 'plPL', 'Przenośny rozdrabniacz Zinfizzlexa', '', 0),
(17411, 'plPL', 'Piła parowa', '', 0),
(17442, 'plPL', 'Rozkazy natarcia Mroźnych Wilków', 'Przekaż mistrzowi wojennemu Garrickowi na Polu Niezgody', 0),
(17522, 'plPL', 'Zapasy z Żelaznej Głębi', '', 0),
(17542, 'plPL', 'Zapasy z Mrozokłów', '', 0),
(17626, 'plPL', 'Kaganiec Mroźnych Wilków', '', 0),
(17642, 'plPL', 'Skóra alterackiego barana', '', 0),
(17643, 'plPL', 'Skóra mroźnego wilka', '', 0),
(17689, 'plPL', 'Obroża treningowa Gromdardy', '', 0),
(18142, 'plPL', 'Odcięta głowa nocnego elfa', '', 0),
(18146, 'plPL', 'Mojo trolla z Mrocznej Włóczni', '', 0),
(18226, 'plPL', 'Zapieczętowany pakt', '', 0),
(18227, 'plPL', 'Smoczek bez końcówki', 'Ten przedmiot był często używany.', 0),
(18228, 'plPL', 'Zdjęcie z autografami Forora i Tigule\'a', 'Zagadka pozostaje nierozwiązana.', 0),
(18229, 'plPL', 'Poradnik ekstremalnego wędkowania Nata Pagle\'a', 'W tej książce brakuje wszystkich stron oprócz ostatniej.', 0),
(18233, 'plPL', 'Chusteczka mokra od łez', 'Właścicielowi tego przedmiotu przydałby się chyba uścisk.', 0),
(18234, 'plPL', 'Dokument z „Pukawek z Importu”', 'Chyba udaje ci się odczytać jakieś liczby. Wygląda to na rachunek za naprawę.', 0);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2611, 'plPL', '...i właśnie tam znajdziesz legendarny miecz Szkarłatnego najwyższego lorda, Spopielacz.$B$BNiesamowite, na co można się natknąć podczas zwykłego dnia na rybach, co nie?', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(8750, 'plPL', '', 'Moja wiara kieruje moimi czynami. Wiem, że Ivus przybędzie.', 0),
(8763, 'plPL', 'Zestrzelił mnie ten lekkomyślny głupiec, Mulverick. Obawiam się, że jeśli nie wrócę do bazy, wszystko będzie stracone! Trzeba powstrzymać Mulvericka i jego eskadrę jeźdźców wojennych!', '', 0),
(8765, 'plPL', 'Nie mogę w to uwierzyć... Leciałem na rutynowy zwiad nad centralną strefą zdemilitaryzowaną, kiedy rozpętało się piekło! Widziałem, jak dowódca skrzydła Hordy, Mulverick, strąca i Ichmana, i Slidore\'a! Wpadłem w gniew, oderwałem się od skrzydłowego i sprowadziłem tego pozera, Mulvericka, na ziemię. Niestety, zanim się rozbił, zahaczył mojego gryfa i też musiałem lądować. Skończyło się na tym, że pojmali mnie ci dzikusi.$B$BMuszę wrócić do bazy! Pomocy!', '', 0),
(8854, 'plPL', 'Mówią, że armia maszeruje na własnym żołądku, i to prawda. Żeby ofensywa się powiodła, żołnierze muszą być dobrze nakarmieni i dobrze zaopatrzeni.', '', 0),
(8901, 'plPL', 'Śmierć Mroźnym Wilkom!', '', 0),
(8909, 'plPL', '', 'Rdzenne barany Alterak są niezbędne do działania naszej kawalerii!', 0),
(9128, 'plPL', 'Ile jeszcze zapasów potrzeba, by wysłać natarcie lądowe?', 'Ile jeszcze zapasów potrzeba, by wysłać natarcie lądowe?', 0),
(9151, 'plPL', 'Ile jeszcze zapasów potrzeba do następnego ulepszenia?', 'Ile jeszcze zapasów potrzeba do następnego ulepszenia?', 0),
(9155, 'plPL', 'Mam już prawie dość zapasów, by ulepszyć nasze oddziały.', '', 0),
(9164, 'plPL', 'Nasze oddziały nie są ulepszone, a nie mam dość zapasów, by je ulepszyć.', '', 0),
(9165, 'plPL', 'Nasze oddziały zostały ulepszone do stopnia doświadczonych, ale nie mam dość zapasów, by ulepszyć je do stopnia weteranów.', '', 0);
